#!/usr/bin/env python3
"""Independent verifier for generated math worksheets.

Re-parses each problem in worksheet.txt, evaluates it from scratch,
and compares against key.txt.

Usage:
    python check_key.py [worksheet.txt] [key.txt]

Prints PASS and exits 0 on success; prints the first mismatch and exits 1.
"""

import re
import sys

from worksheet import DIV, MUL

TOKEN_RE = re.compile(r"\d+|[()+\-x*\u00f7/]")

PRECEDENCE = {"+": 1, "-": 1, MUL: 2, "*": 2, DIV: 2, "/": 2}


def tokenize(expr):
    tokens = TOKEN_RE.findall(expr.replace(" ", ""))
    if "".join(tokens) != expr.replace(" ", ""):
        raise ValueError(f"unparseable expression: {expr!r}")
    return tokens


def evaluate(expr):
    """Shunting-yard evaluation supporting parentheses and + - x ÷."""
    output = []
    ops = []
    for tok in tokenize(expr):
        if tok.isdigit():
            output.append(int(tok))
        elif tok == "(":
            ops.append(tok)
        elif tok == ")":
            while ops and ops[-1] != "(":
                output.append(ops.pop())
            if not ops:
                raise ValueError(f"unbalanced parentheses: {expr!r}")
            ops.pop()  # discard "("
        else:  # operator
            while ops and ops[-1] != "(" and PRECEDENCE[ops[-1]] >= PRECEDENCE[tok]:
                output.append(ops.pop())
            ops.append(tok)
    while ops:
        if ops[-1] == "(":
            raise ValueError(f"unbalanced parentheses: {expr!r}")
        output.append(ops.pop())

    stack = []
    for tok in output:
        if isinstance(tok, int):
            stack.append(tok)
        else:
            b = stack.pop()
            a = stack.pop()
            if tok in (MUL, "*"):
                stack.append(a * b)
            elif tok in (DIV, "/"):
                if b == 0 or a % b != 0:
                    raise ValueError(f"inexact division in {expr!r}")
                stack.append(a // b)
            elif tok == "+":
                stack.append(a + b)
            elif tok == "-":
                stack.append(a - b)
            else:
                raise ValueError(f"unknown operator: {tok!r}")
    if len(stack) != 1:
        raise ValueError(f"malformed expression: {expr!r}")
    return stack[0]


LINE_RE = re.compile(r"^(\d+)\)\s*(.+?)\s*$")


def parse_lines(path):
    entries = {}
    with open(path) as f:
        for lineno, raw in enumerate(f, start=1):
            raw = raw.rstrip("\n")
            if not raw.strip():
                continue
            m = LINE_RE.match(raw)
            if not m:
                raise ValueError(f"{path}:{lineno}: bad line format: {raw!r}")
            num, body = int(m.group(1)), m.group(2)
            if num in entries:
                raise ValueError(f"{path}:{lineno}: duplicate problem number {num}")
            entries[num] = body
    return entries


def check(worksheet_path="worksheet.txt", key_path="key.txt"):
    problems = parse_lines(worksheet_path)
    answers = parse_lines(key_path)

    if set(problems) != set(answers):
        missing_w = sorted(set(answers) - set(problems))
        missing_k = sorted(set(problems) - set(answers))
        return None, (
            f"MISMATCH: problem-number sets differ "
            f"(only in worksheet: {missing_w}, only in key: {missing_k})"
        )

    for num in sorted(problems):
        expr = problems[num]
        expected_raw = answers[num]
        actual = evaluate(expr)
        try:
            expected = int(expected_raw)
        except ValueError:
            return num, (
                f"MISMATCH at {num}): {expr} = ... "
                f"key has non-integer answer {expected_raw!r}, computed {actual}"
            )
        if actual != expected:
            return num, (
                f"MISMATCH at {num}): {expr} = {actual} "
                f"(key says {expected})"
            )
    return None, f"PASS ({len(problems)} problems checked)"


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    worksheet_path = argv[0] if len(argv) > 0 else "worksheet.txt"
    key_path = argv[1] if len(argv) > 1 else "key.txt"
    try:
        num, message = check(worksheet_path, key_path)
    except (OSError, ValueError) as exc:
        print(f"FAIL: {exc}")
        return 1
    print(message)
    return 0 if message.startswith("PASS") else 1


if __name__ == "__main__":
    sys.exit(main())

